const body = $input.first().json.body || $input.first().json || {};
const messageText = (body.messageText || body.message || '').trim();
const senderPhone = body.senderPhone || body.phone || 'Unknown';
const senderName = body.senderName || body.name || 'Valued Patient';
const eventType = body.event || 'whatsapp_message';

// Load or initialize multi-turn session
let s = Object.assign({
  step: 0,
  service: null,
  patientName: null,
  patientPhone: null,
  preferredTime: null,
  askedAboutFee: false,
  quotedFee: '$50-$100',
  reaskCount: 0,
  lastBotMessage: '',
  isBooked: false,
  isEmergency: false,
  subStage: null
}, body.session || {});

const lower = messageText.toLowerCase();

// Smart time extraction helper
function extractCleanTime(text, existingTime) {
  const clean = text.trim();
  const l = clean.toLowerCase();

  // 1. Detect day
  let day = '';
  const dayMatch = l.match(/\b(tomorrow|today|tonight|monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b/i);
  if (dayMatch) {
    day = dayMatch[1].charAt(0).toUpperCase() + dayMatch[1].slice(1).toLowerCase();
  }

  // 2. Detect slot or hour
  let slotOrHour = '';
  const hourMatch = l.match(/\b(\d{1,2})(?::(\d{2}))?\s*(am|pm)\b/i);
  if (hourMatch) {
    const h = hourMatch[1];
    const m = hourMatch[2] ? (':' + hourMatch[2]) : ':00';
    const ampm = hourMatch[3].toUpperCase();
    slotOrHour = h + m + ' ' + ampm;
  } else if (/morning/i.test(l)) {
    slotOrHour = 'Morning';
  } else if (/afternoon/i.test(l)) {
    slotOrHour = 'Afternoon';
  } else if (/evening/i.test(l)) {
    slotOrHour = 'Evening';
  }

  if (day && slotOrHour) {
    return day + ' ' + slotOrHour;
  } else if (slotOrHour) {
    const existingDayMatch = (existingTime || '').match(/\b(Tomorrow|Today|Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday)\b/i);
    if (existingDayMatch) {
      return existingDayMatch[1] + ' ' + slotOrHour;
    }
    return slotOrHour;
  } else if (day) {
    return day;
  }

  return clean
    .replace(/^(?:yeah|yes|no|actually|please|ok|okay|sure|hey|hi)[\s,]+/i, '')
    .replace(/^(?:i\s+(?:will|want\s+to|would\s+like\s+to|need\s+to)\s+)?(?:change|switch|make|reschedule|move)\s+(?:it\s+)?(?:to|into|for)?\s+/i, '')
    .trim() || clean;
}

// 1. Strict Rule 5: Fee Inquiry Detection
const isFeeQuestion = /fee|cost|price|charge|rate|how much|pricing/i.test(lower);
let feeExplanation = '';
if (isFeeQuestion) {
  s.askedAboutFee = true;
  s.quotedFee = '$50-$100';
  if (/emergency/i.test(lower)) {
    feeExplanation = 'Our standard consultation fee is $50–$100 depending on the case, with no extra emergency surcharges.';
  } else {
    feeExplanation = 'Our standard consultation fee is $50–$100 depending on the case.';
  }
}

// 2. Strict Rule 4: Formatting Summary Generator (Exact Template)
function formatSummary(state) {
  const feeLine = state.askedAboutFee ? ('\n- Estimated Fee: ' + state.quotedFee) : '';
  return [
    'Great, I have your details. Here is the summary of your appointment:',
    '- Name: ' + (state.patientName || 'Valued Patient'),
    '- Phone: ' + (state.patientPhone || senderPhone),
    '- Service: ' + (state.service || 'Routine'),
    '- Date & Time: ' + (state.preferredTime || 'Tomorrow Afternoon') + feeLine,
    '',
    'Does this look correct, or do you need to change the date and time?'
  ].join('\n');
}

let reply = '';
let syncAction = 'NONE'; // 'APPEND', 'UPDATE', 'NONE'

// Detect Fresh Conversation, Missed Call, or Reset Commands
const isExplicitReset = /^(reset|restart|start\s*over|clear|cancel|new\s*booking)$/i.test(lower.trim());
const isMissedCallIntent = (/missed/i.test(lower) && /call/i.test(lower));
const isBookingIntent = (/book/i.test(lower) && /appointment/i.test(lower)) || /new\s+appointment/i.test(lower);
const isPureGreeting = /^(hi|hello|hey|good\s*(?:morning|afternoon|evening))[!., ]*$/i.test(lower.trim());

// Reset condition:
// - If previous booking was completed
// - If user explicitly sends a reset command
// - If user says "missed a call"
// - If user says "hi/hello" or "book appointment" while sitting in Step 5 or 6 (preventing stale loops)
if (
  s.step === 'COMPLETED' ||
  isExplicitReset ||
  isMissedCallIntent ||
  ((s.step === 5 || s.step === 6) && (isPureGreeting || isBookingIntent))
) {
  s.step = 0;
  s.service = null;
  s.patientName = null;
  s.patientPhone = null;
  s.preferredTime = null;
  s.subStage = null;
  s.reaskCount = 0;
  s.isBooked = false;
  s.isEmergency = false;
  s.askedAboutFee = false;
}

// STEP 0 / STEP 1: Greeting & Service Type
if (s.step === 0 || s.step === 1) {
  const isEmergIntent = !isFeeQuestion && /emergency|urgent|severe\s*pain|toothache|broken\s*tooth|bleeding|swelling/i.test(lower);
  const isRoutineIntent = !isFeeQuestion && /routine|check-?up|cleaning|regular|consult|exam|whitening|normal/i.test(lower);

  if ((s.step === 0 || isPureGreeting || isMissedCallIntent || isBookingIntent) && !isEmergIntent && !isRoutineIntent) {
    s.step = 1;
    s.reaskCount = 0;
    const greetingQ = "Hello! I am the receptionist for Apex Dental Clinic. Are you looking for an emergency visit or a normal routine check-up?";
    reply = feeExplanation ? (feeExplanation + '\n\n' + greetingQ) : greetingQ;
    s.lastBotMessage = reply;
  } else if (isEmergIntent) {
    s.service = 'Emergency';
    s.isEmergency = true;
    s.step = 2;
    s.reaskCount = 0;
    const nameQ = "Could you please provide your full name?";
    reply = feeExplanation ? (feeExplanation + '\n\nThank you. ' + nameQ) : ('Thank you. ' + nameQ);
    s.lastBotMessage = reply;
  } else if (isRoutineIntent) {
    s.service = 'Routine';
    s.isEmergency = false;
    s.step = 2;
    s.reaskCount = 0;
    const nameQ = "Could you please provide your full name?";
    reply = feeExplanation ? (feeExplanation + '\n\nThank you. ' + nameQ) : ('Thank you. ' + nameQ);
    s.lastBotMessage = reply;
  } else {
    // Clarify / Re-ask (Strict Rule 2 & 3)
    s.step = 1;
    s.reaskCount = (s.reaskCount || 0) + 1;
    const reasks = [
      "Are you looking for an emergency visit or a normal routine check-up?",
      "To get you scheduled properly at Apex Dental Clinic, is this visit for an emergency or a normal routine check-up?",
      "Could you please clarify whether you need urgent emergency care or a normal routine check-up?"
    ];
    const q = reasks[s.reaskCount % reasks.length];
    reply = feeExplanation ? (feeExplanation + '\n\n' + q) : (isFeeQuestion ? q : ("I'd be happy to help with that later, but first, let's get your appointment scheduled. " + q));
    s.lastBotMessage = reply;
  }

} else if (s.step === 2) {
  // STEP 2: Collect Name
  if (isFeeQuestion && !/[a-z]{2,}\s+[a-z]{2,}/i.test(messageText)) {
    reply = feeExplanation + '\n\nCould you please provide your full name?';
    s.lastBotMessage = reply;
  } else {
    let cleanName = messageText
      .replace(/^(my name is|i am|this is|call me|name is|it's|it is)\s+/i, '')
      .replace(/[!?,;]+$/, '')
      .trim();

    const isOffTopic = /weather|joke|football|cricket|who are you|what is your name|where are you/i.test(cleanName);
    const hasLetters = /[a-zA-Z]{2,}/.test(cleanName);

    if (!cleanName || !hasLetters || isOffTopic) {
      s.reaskCount = (s.reaskCount || 0) + 1;
      const reasks = [
        "I'd be happy to help with that later, but first, let's get your appointment scheduled. Could you please provide your full name?",
        "May I have your first and last name for our clinic records?",
        "Please provide your full name so we can proceed with your booking."
      ];
      reply = reasks[s.reaskCount % reasks.length];
      s.lastBotMessage = reply;
    } else {
      s.patientName = cleanName;
      s.step = 3;
      s.reaskCount = 0;
      const phoneQ = "Thank you, " + s.patientName + ". What is your phone number?";
      reply = feeExplanation ? (feeExplanation + '\n\n' + phoneQ) : phoneQ;
      s.lastBotMessage = reply;
    }
  }

} else if (s.step === 3) {
  // STEP 3: Collect Phone Number
  if (isFeeQuestion && !/\d{6,}/.test(messageText)) {
    reply = feeExplanation + '\n\nWhat is your phone number?';
    s.lastBotMessage = reply;
  } else {
    let rawDigits = messageText.replace(/[^0-9]/g, '');
    if (/this number|same|my whatsapp|current number/i.test(lower)) {
      rawDigits = senderPhone.replace(/[^0-9]/g, '');
    }

    if (!rawDigits || rawDigits.length < 7) {
      s.reaskCount = (s.reaskCount || 0) + 1;
      const reasks = [
        "I'd be happy to help with that later, but first, let's get your appointment scheduled. What is your phone number?",
        "Please provide the best contact phone number so our clinical team can reach you.",
        "Could you please share a valid direct phone number for the booking?"
      ];
      reply = reasks[s.reaskCount % reasks.length];
      s.lastBotMessage = reply;
    } else {
      // Store clean phone for user display
      s.patientPhone = messageText.trim().startsWith('+') ? ('+' + rawDigits) : (rawDigits.startsWith('0') ? rawDigits : ('0' + rawDigits));
      s.step = 4;
      s.reaskCount = 0;
      const timeQ = "What is your preferred day, and whether you prefer a morning or afternoon appointment?";
      reply = feeExplanation ? (feeExplanation + '\n\nGot it. ' + timeQ) : ('Got it. ' + timeQ);
      s.lastBotMessage = reply;
    }
  }

} else if (s.step === 4) {
  // STEP 4: Collect Preferred Time -> STEP 5: SAVE NEW ROW & Send Summary
  if (isFeeQuestion && !/morning|afternoon|pm|am|tomorrow|today|monday|tuesday|wednesday|thursday|friday|saturday|sunday|\d/i.test(lower)) {
    reply = feeExplanation + '\n\nWhat is your preferred day, and whether you prefer a morning or afternoon appointment?';
    s.lastBotMessage = reply;
  } else {
    const hasTimeContext = /morning|afternoon|pm|am|tomorrow|today|tonight|monday|tuesday|wednesday|thursday|friday|saturday|sunday|at\s+\d|\d{1,2}:\d{2}|\d{1,2}\s*(?:am|pm)/i.test(lower);
    if (!hasTimeContext) {
      s.reaskCount = (s.reaskCount || 0) + 1;
      const reasks = [
        "I'd be happy to help with that later, but first, let's get your appointment scheduled. What is your preferred day, and whether you prefer a morning or afternoon appointment?",
        "Which day works best for you, and would you prefer a morning or afternoon appointment?",
        "Please let me know your preferred day and whether morning or afternoon works better for you."
      ];
      reply = reasks[s.reaskCount % reasks.length];
      s.lastBotMessage = reply;
    } else {
      s.preferredTime = extractCleanTime(messageText, '');
      s.step = 5;
      s.isBooked = true;
      syncAction = 'APPEND'; // Step 5: SAVE NEW ROW in Google Sheet

      reply = formatSummary(s);
      s.lastBotMessage = reply;
    }
  }

} else if (s.step === 5 || s.step === 6) {
  // STEP 5 & STEP 6: Confirmation & Modifications
  if (s.subStage === 'AWAITING_NEW_TIME') {
    s.preferredTime = extractCleanTime(messageText, s.preferredTime);
    s.subStage = null;
    s.step = 6;
    s.isBooked = true;
    syncAction = 'UPDATE'; // Step 6: UPDATE THAT SPECIFIC ROW in Google Sheet
    reply = formatSummary(s);
    s.lastBotMessage = reply;
  } else {
    // Check if user confirmed
    const isConfirmation = /^(yes|yeah|yep|sure|correct|looks good|confirm|confirmed|that's right|perfect|all good|ok|okay)[!.]*$/i.test(lower) ||
      /looks good|is correct|please confirm|sounds good/i.test(lower);

    if (isConfirmation) {
      s.step = 'COMPLETED';
      s.subStage = null;
      s.isBooked = false;
      syncAction = 'NONE';
      reply = "Perfect, your appointment is booked. We look forward to seeing you at Apex Dental Clinic!";
      s.lastBotMessage = reply;
    } else {
      // Check if user wants to change date and time
      const wantsChange = /change|reschedule|switch|different (?:day|time|date)|another (?:day|time|date)|not (?:tomorrow|morning|afternoon)|update/i.test(lower);
      const hasNewTime = /morning|afternoon|pm|am|tomorrow|today|monday|tuesday|wednesday|thursday|friday|saturday|sunday|\d{1,2}:\d{2}|\d{1,2}\s*(?:am|pm)/i.test(lower);

      if (wantsChange && hasNewTime) {
        s.preferredTime = extractCleanTime(messageText, s.preferredTime);
        s.step = 6;
        s.subStage = null;
        s.isBooked = true;
        syncAction = 'UPDATE'; // UPDATE THAT SPECIFIC ROW
        reply = formatSummary(s);
        s.lastBotMessage = reply;
      } else if (wantsChange) {
        s.step = 6;
        s.subStage = 'AWAITING_NEW_TIME';
        s.isBooked = false;
        syncAction = 'NONE';
        s.reaskCount = (s.reaskCount || 0) + 1;
        const reasks = [
          "What is your new preferred date and time?",
          "Which day and time would you like to reschedule your appointment to?",
          "Please tell me the new preferred date and time you would like."
        ];
        reply = reasks[s.reaskCount % reasks.length];
        s.lastBotMessage = reply;
      } else if (isFeeQuestion) {
        reply = feeExplanation + '\n\nDoes this look correct, or do you need to change the date and time?';
        s.lastBotMessage = reply;
      } else {
        s.reaskCount = (s.reaskCount || 0) + 1;
        const reasks = [
          "I'd be happy to help with that later, but first, let's get your appointment scheduled. Does this look correct, or do you need to change the date and time?",
          "Please let me know if your appointment details look correct, or if you need to change the date and time."
        ];
        reply = reasks[s.reaskCount % reasks.length];
        s.lastBotMessage = reply;
      }
    }
  }
}

// 3. Clinical Triage Status & Notes (Clean & Direct)
const isEmergCase = s.service === 'Emergency';
const triageStatus = isEmergCase ? 'Emergency Case' : 'Standard';
const notes = isEmergCase
  ? 'Emergency Case - Apex Dental Clinic'
  : 'Standard Appointment - Apex Dental Clinic';

// Format phone for Google Sheets matching:
const displayPhone = s.patientPhone || senderPhone;
const rawDigits = String(displayPhone).replace(/\D/g, '');
const safePhone = rawDigits.replace(/^0+/, '');

// Stamp lastUpdated
s.lastUpdated = new Date().toISOString();

return {
  json: {
    'TIMESTAMP': new Date().toLocaleString(),
    'PATIENT NAME': s.patientName || senderName,
    'PHONE NUMBER': safePhone,
    'SERVICE / REASON': s.service || 'Routine',
    'PREFERRED TIME': s.preferredTime || 'Pending Confirmation',
    'TRIAGE STATUS': triageStatus,
    'NOTES': notes,
    'reply': reply,
    'syncAction': syncAction,
    'isBooked': s.isBooked,
    'isEmergency': isEmergCase,
    'updatedSession': s
  }
};

const item = $input.first().json;
return {
  json: {
    'TIMESTAMP': item['TIMESTAMP'],
    'PATIENT NAME': item['PATIENT NAME'],
    'PHONE NUMBER': item['PHONE NUMBER'],
    'SERVICE / REASON': item['SERVICE / REASON'],
    'PREFERRED TIME': item['PREFERRED TIME'],
    'TRIAGE STATUS': item['TRIAGE STATUS'],
    'NOTES': item['NOTES']
  }
};
